from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Loop through the input string to identify and separate groups of nested parentheses
    result = []
    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append("(")
            current_group += char
        elif char == ")":
            stack.pop()
            current_group += char
            if not stack:
                result.append(current_group)
                current_group = ""

    # Step 3: Check if each group is balanced by counting the number of opening and closing parentheses
    def is_balanced(group):
        count = 0
        for char in group:
            if char == "(":
                count += 1
            elif char == ")":
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Step 4: Return the list of balanced groups as separate strings
    return [group for group in result if is_balanced(group)]

